@Component("bank-handler")
@ProcessingGroup("bank-processing-group")
public class BankEventHandler {
	
	// core constructor
	BankEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateBankEvent
     */
    @EventHandler
    public void handle( CreateBankEvent event) {
        entityManager.persist(new Bank(event.getBankId(), event.getName(), event.getLegalName(), event.getSwiftBic(), event.getHeadquartersCountry(), event.getWebsite(), event.getBranches(), event.getProducts(), event.getCustomers(), event.getAccounts(), event.getPaymentCards(), event.getLoanAccounts(), event.getExchangeRates(), event.getConsents(), event.getThirdPartyProviders()));
    }

    /*
     * @param	event UpdateBankEvent
     */
    @EventHandler
    public Bank handle( UpdateBankEvent event) {
    	entityManager.merge(new Bank(event.getBankId(), event.getName(), event.getLegalName(), event.getSwiftBic(), event.getHeadquartersCountry(), event.getWebsite(), event.getBranches(), event.getProducts(), event.getCustomers(), event.getAccounts(), event.getPaymentCards(), event.getLoanAccounts(), event.getExchangeRates(), event.getConsents(), event.getThirdPartyProviders()));
    }
    
    /*
     * @param	event DeleteBankEvent
     */
    @EventHandler
    public void on( DeleteBankEvent event) {
    	Bank entity = new Bank();
   
    	// ------------------------------------------
    	// apply the BankId
    	// ------------------------------------------
    	entity.setBankId( event.getBankId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final BankRepository bankEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(BankEventHandler.class.getName());

}
